// prettier: formats files with Prettier (its standalone build and plugins).
const prettier = require('standalone.js');
const plugins = ['babel', 'estree', 'typescript', 'postcss', 'markdown', 'html', 'yaml', 'graphql'].map((p) => require(`plugins/${p}.js`));
const usage = `usage: prettier [--write | --check] [options] file...
  (no flag)          print the formatted file
  -w, --write        format the files in place
  -c, --check        list files that are not formatted (exit 1 if any)
  --parser NAME      babel, typescript, css, scss, less, json, markdown, html, vue, yaml, graphql
  --stdin-filepath F format stdin as if it were the file F
  --print-width N  --tab-width N  --use-tabs  --single-quote  --no-semi  --trailing-comma all|es5|none
Options also come from .prettierrc (JSON) in the folder.`;
const opts = {};
let mode = 'print';
const files = [];
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === '-h' || a === '--help') return print(usage);
  else if (a === '-v' || a === '--version') return print(prettier.version);
  else if (a === '-w' || a === '--write') mode = 'write';
  else if (a === '-c' || a === '--check' || a === '-l' || a === '--list-different') mode = 'check';
  else if (a === '--parser') opts.parser = args[++i];
  else if (a === '--stdin-filepath') opts.filepath = args[++i];
  else if (a === '--print-width') opts.printWidth = Number(args[++i]);
  else if (a === '--tab-width') opts.tabWidth = Number(args[++i]);
  else if (a === '--use-tabs') opts.useTabs = true;
  else if (a === '--single-quote') opts.singleQuote = true;
  else if (a === '--no-semi') opts.semi = false;
  else if (a === '--trailing-comma') opts.trailingComma = args[++i];
  else if (a.startsWith('-')) {
    console.error(`prettier: unknown option ${a}\n${usage}`);
    exit(2);
  } else files.push(a);
}
let config = {};
if (await fs.exists('.prettierrc')) {
  try {
    config = JSON.parse(await fs.readText('.prettierrc'));
  } catch {
    console.error('prettier: .prettierrc is not JSON; ignoring it');
  }
}
if (!files.length) {
  if (!stdin) return print(usage);
  if (!opts.parser && !opts.filepath) {
    console.error('prettier: formatting stdin needs --parser or --stdin-filepath');
    exit(2);
  }
  const outText = await prettier.format(stdin, { ...config, ...opts, plugins });
  return void console.log(outText.replace(/\n$/, ''));
}
let failed = 0;
let unformatted = 0;
for (const file of files) {
  try {
    const text = await fs.readText(file);
    const o = { ...config, ...opts, filepath: file, plugins };
    if (mode === 'check') {
      if (!(await prettier.check(text, o))) (unformatted++, print(file));
      continue;
    }
    const formatted = await prettier.format(text, o);
    if (mode === 'write') {
      if (formatted !== text) await fs.writeFile(file, formatted);
      print(`${file}${formatted === text ? ' (unchanged)' : ''}`);
    } else console.log(formatted.replace(/\n$/, ''));
  } catch (e) {
    failed++;
    console.error(`${file}: ${String(e?.message ?? e).split('\n')[0]}`);
  }
}
if (failed) exit(2);
if (unformatted) exit(1);

// marked: converts Markdown to HTML.
const { marked } = require('lib/marked.umd.js');
const usage = `usage: marked [file] [-o out.html] [--page] [--breaks] [--no-gfm]
  Reads the file (or stdin) and prints HTML, or writes it with -o.
  --page     a whole HTML page (with a title and simple styles), not a fragment`;
let input = null;
let output = null;
let page = false;
const o = { gfm: true, breaks: false };
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === '-h' || a === '--help') return print(usage);
  else if (a === '-o' || a === '--output') output = args[++i];
  else if (a === '--page' || a === '-s' || a === '--standalone') page = true;
  else if (a === '--breaks') o.breaks = true;
  else if (a === '--no-gfm') o.gfm = false;
  else if (a.startsWith('-')) {
    console.error(`marked: unknown option ${a}\n${usage}`);
    exit(2);
  } else input = a;
}
const md = input ? await fs.readText(input) : stdin;
if (!md && !input) return print(usage);
let html = await marked.parse(md, o);
if (page) {
  const title = (/^#\s+(.+)$/m.exec(md)?.[1] ?? (input ?? 'Document')).replace(/[<&>"]/g, (c) => `&#${c.charCodeAt(0)};`);
  html = `<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>${title}</title>\n<style>body{font:16px/1.6 system-ui,sans-serif;max-width:46rem;margin:2rem auto;padding:0 1rem;color:#222}pre{background:#f4f4f4;padding:.75rem;overflow:auto}code{font-family:ui-monospace,monospace}table{border-collapse:collapse}td,th{border:1px solid #ccc;padding:.25rem .5rem}img{max-width:100%}@media (prefers-color-scheme:dark){body{background:#161616;color:#ddd}pre{background:#222}}</style>\n</head>\n<body>\n${html}</body>\n</html>\n`;
}
if (output) {
  await fs.writeFile(output, html);
  print(`wrote ${output}`);
} else console.log(html.replace(/\n$/, ''));

// yaml2json / json2yaml: converts between YAML and JSON (js-yaml).
const yaml = require('dist/js-yaml.min.js');
const toJson = args[0] === '--to-json';
const rest = args.slice(1);
const name = toJson ? 'yaml2json' : 'json2yaml';
const usage = `usage: ${name} [file] [-o out] ${toJson ? '[--indent N] [--compact]' : '[--indent N]'}\n  Reads the file (or stdin) and prints ${toJson ? 'JSON' : 'YAML'}, or writes it with -o.`;
let input = null;
let output = null;
let indent = 2;
for (let i = 0; i < rest.length; i++) {
  const a = rest[i];
  if (a === '-h' || a === '--help') return print(usage);
  else if (a === '-o' || a === '--output') output = rest[++i];
  else if (a === '--indent') indent = Number(rest[++i]) || 2;
  else if (a === '--compact') indent = 0;
  else if (a.startsWith('-')) {
    console.error(`${name}: unknown option ${a}\n${usage}`);
    exit(2);
  } else input = a;
}
const text = input ? await fs.readText(input) : stdin;
if (!text && !input) return print(usage);
let result;
try {
  if (toJson) {
    const docs = yaml.loadAll(text);
    result = JSON.stringify(docs.length === 1 ? docs[0] : docs, null, indent || undefined) + '\n';
  } else result = yaml.dump(JSON.parse(text), { indent, lineWidth: 100, noRefs: true });
} catch (e) {
  console.error(`${name}: ${String(e?.message ?? e)}`);
  exit(1);
}
if (output) {
  await fs.writeFile(output, result);
  print(`wrote ${output}`);
} else console.log(result.replace(/\n$/, ''));

// sheet: spreadsheets (Excel .xlsx/.xls, OpenDocument .ods, CSV, JSON) with SheetJS.
const XLSX = require('lib/xlsx.full.min.js');
const usage = `usage: sheet <command> …
  sheet info book.xlsx                      sheets, their size and first row
  sheet csv book.xlsx [--sheet Name] [-o out.csv]
  sheet json book.xlsx [--sheet Name] [-o out.json]   rows as objects (first row = keys)
  sheet make in.csv|in.json … -o out.xlsx  one sheet per input (named after the file)
  sheet convert in.xlsx out.(xlsx|xls|ods|csv|html|json)`;
const opts = { sheet: null, out: null };
const rest = [];
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === '-h' || a === '--help') return print(usage);
  if (a === '--sheet' || a === '-s') opts.sheet = args[++i];
  else if (a === '-o' || a === '--output') opts.out = args[++i];
  else rest.push(a);
}
const [cmd, ...files] = rest;
if (!cmd) return print(usage);
const fail = (msg) => (console.error(`sheet: ${msg}`), exit(1));
const ext = (p) => (/\.([^./]+)$/.exec(p)?.[1] ?? '').toLowerCase();
const read = async (p) => {
  const e = ext(p);
  if (e === 'csv' || e === 'tsv' || e === 'txt') return XLSX.read(await fs.readText(p), { type: 'string', raw: false, FS: e === 'tsv' ? '\t' : undefined });
  if (e === 'json') {
    const data = JSON.parse(await fs.readText(p));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, Array.isArray(data) && Array.isArray(data[0]) ? XLSX.utils.aoa_to_sheet(data) : XLSX.utils.json_to_sheet(Array.isArray(data) ? data : [data]), 'Sheet1');
    return wb;
  }
  return XLSX.read(await fs.readFile(p), { type: 'array', cellDates: true });
};
const pick = (wb) => {
  const name = opts.sheet ?? wb.SheetNames[0];
  const ws = wb.Sheets[name];
  if (!ws) fail(`no sheet "${name}" (sheets: ${wb.SheetNames.join(', ')})`);
  return ws;
};
const emit = async (text) => {
  if (opts.out) {
    await fs.writeFile(opts.out, text);
    print(`wrote ${opts.out}`);
  } else console.log(text.replace(/\n$/, ''));
};
const write = async (wb, path) => {
  const e = ext(path);
  if (e === 'csv') return fs.writeFile(path, XLSX.utils.sheet_to_csv(pick(wb)));
  if (e === 'json') return fs.writeFile(path, JSON.stringify(XLSX.utils.sheet_to_json(pick(wb)), null, 2));
  if (e === 'html') return fs.writeFile(path, XLSX.utils.sheet_to_html(pick(wb)));
  const bookType = { xlsx: 'xlsx', xls: 'biff8', ods: 'ods', xlsb: 'xlsb' }[e];
  if (!bookType) fail(`cannot write .${e} (xlsx, xls, ods, xlsb, csv, json or html)`);
  return fs.writeFile(path, new Uint8Array(XLSX.write(wb, { type: 'array', bookType })));
};

if (cmd === 'info') {
  if (!files[0]) fail('which file?');
  const wb = await read(files[0]);
  for (const name of wb.SheetNames) {
    const ws = wb.Sheets[name];
    const ref = ws['!ref'];
    const r = ref ? XLSX.utils.decode_range(ref) : null;
    const head = XLSX.utils.sheet_to_json(ws, { header: 1, range: 0 })[0] ?? [];
    print(`${name}: ${r ? `${r.e.r - r.s.r + 1} rows × ${r.e.c - r.s.c + 1} columns (${ref})` : 'empty'}${head.length ? `\n  first row: ${head.join(' | ')}` : ''}`);
  }
} else if (cmd === 'csv') {
  if (!files[0]) fail('which file?');
  await emit(XLSX.utils.sheet_to_csv(pick(await read(files[0]))));
} else if (cmd === 'json') {
  if (!files[0]) fail('which file?');
  await emit(JSON.stringify(XLSX.utils.sheet_to_json(pick(await read(files[0])), { defval: null }), null, 2));
} else if (cmd === 'make') {
  if (!files.length || !opts.out) fail('usage: sheet make in.csv|in.json … -o out.xlsx');
  const wb = XLSX.utils.book_new();
  for (const f of files) {
    const src = await read(f);
    const base = f.replace(/^.*\//, '').replace(/\.[^.]+$/, '').slice(0, 31) || 'Sheet';
    let name = base;
    for (let n = 2; wb.SheetNames.includes(name); n++) name = `${base.slice(0, 28)} ${n}`;
    XLSX.utils.book_append_sheet(wb, src.Sheets[src.SheetNames[0]], name);
  }
  await write(wb, opts.out);
  print(`wrote ${opts.out} (${wb.SheetNames.length} sheet${wb.SheetNames.length === 1 ? '' : 's'})`);
} else if (cmd === 'convert') {
  const [from, to] = files;
  if (!from || !to) fail('usage: sheet convert in.xlsx out.ods');
  await write(await read(from), to);
  print(`wrote ${to}`);
} else fail(`unknown command ${cmd}\n${usage}`);

// pdf: read, combine and make PDF files (pdf-lib; text with pdf.js).
const PDFLib = require('lib/pdf-lib.min.js');
const usage = `usage: pdf <command> …
  pdf info file.pdf                        pages, size, title, author
  pdf text file.pdf [--pages 1-3] [-o out.txt]   the text, page by page
  pdf merge a.pdf b.pdf … -o out.pdf
  pdf pages file.pdf --pages 1-3,7 -o out.pdf    keep (and order) some pages
  pdf rotate file.pdf 90 [--pages 2,4] -o out.pdf
  pdf images a.png b.jpg … -o out.pdf      one page per picture (PNG or JPEG)
  pdf from-text notes.txt|notes.md [-o out.pdf] [--title T]   plain text laid out on A4
Pages are numbered from 1; ranges like 2-5, lists like 1,3,9-10.`;
const opts = { out: null, pages: null, title: null };
const rest = [];
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === '-h' || a === '--help') return print(usage);
  if (a === '-o' || a === '--output') opts.out = args[++i];
  else if (a === '--pages' || a === '-p') opts.pages = args[++i];
  else if (a === '--title') opts.title = args[++i];
  else rest.push(a);
}
const [cmd, ...files] = rest;
if (!cmd) return print(usage);
const fail = (msg) => (console.error(`pdf: ${msg}`), exit(1));
const pagesOf = (spec, count) => {
  if (!spec) return [...Array(count).keys()];
  const out = [];
  for (const part of String(spec).split(',')) {
    const m = /^\s*(\d+)\s*(?:-\s*(\d+|end))?\s*$/.exec(part);
    if (!m) fail(`bad page range "${part}"`);
    const a = Number(m[1]);
    const b = m[2] === undefined ? a : m[2] === 'end' ? count : Number(m[2]);
    for (let p = a; a <= b ? p <= b : p >= b; p += a <= b ? 1 : -1) {
      if (p < 1 || p > count) fail(`page ${p} does not exist (the file has ${count})`);
      out.push(p - 1);
    }
  }
  return out;
};
const load = async (p) => PDFLib.PDFDocument.load(await fs.readFile(p), { ignoreEncryption: true });
const save = async (doc) => {
  if (!opts.out) fail('where to? add -o out.pdf');
  const bytes = await doc.save();
  await fs.writeFile(opts.out, bytes);
  print(`wrote ${opts.out} (${doc.getPageCount()} page${doc.getPageCount() === 1 ? '' : 's'}, ${Math.round(bytes.length / 1024)} KB)`);
};

if (cmd === 'info') {
  if (!files[0]) fail('which file?');
  const doc = await load(files[0]);
  const p = doc.getPage(0).getSize();
  const meta = [['title', doc.getTitle()], ['author', doc.getAuthor()], ['subject', doc.getSubject()], ['creator', doc.getCreator()], ['created', doc.getCreationDate()?.toISOString()]].filter(([, v]) => v);
  print(`${files[0]}: ${doc.getPageCount()} pages, first page ${Math.round(p.width)}×${Math.round(p.height)} pt (${(p.width / 72 * 25.4).toFixed(0)}×${(p.height / 72 * 25.4).toFixed(0)} mm)`);
  for (const [k, v] of meta) print(`${k}: ${v}`);
} else if (cmd === 'text') {
  if (!files[0]) fail('which file?');
  // pdf.js, run on this thread (its worker code is loaded as a library).
  globalThis.pdfjsWorker = require('lib/pdf.worker.min.js');
  const pdfjs = require('lib/pdf.min.js');
  const doc = await pdfjs.getDocument({ data: await fs.readFile(files[0]), isEvalSupported: false, useSystemFonts: false, disableFontFace: true, verbosity: 0 }).promise;
  const parts = [];
  for (const i of pagesOf(opts.pages, doc.numPages)) {
    const page = await doc.getPage(i + 1);
    const content = await page.getTextContent();
    let text = '';
    for (const item of content.items) text += (item.str ?? '') + (item.hasEOL ? '\n' : item.str && !item.str.endsWith(' ') ? ' ' : '');
    parts.push(`--- page ${i + 1} ---\n${text.replace(/[ \t]+\n/g, '\n').trim()}`);
  }
  const all = parts.join('\n\n');
  if (opts.out) {
    await fs.writeFile(opts.out, all);
    print(`wrote ${opts.out}`);
  } else print(all || '(no text: a scanned PDF needs OCR, see the ocr package)');
} else if (cmd === 'merge') {
  if (files.length < 2) fail('give two or more PDF files');
  const out = await PDFLib.PDFDocument.create();
  for (const f of files) {
    const src = await load(f);
    for (const p of await out.copyPages(src, src.getPageIndices())) out.addPage(p);
  }
  await save(out);
} else if (cmd === 'pages') {
  if (!files[0]) fail('which file?');
  const src = await load(files[0]);
  const out = await PDFLib.PDFDocument.create();
  for (const p of await out.copyPages(src, pagesOf(opts.pages, src.getPageCount()))) out.addPage(p);
  await save(out);
} else if (cmd === 'rotate') {
  const [file, deg] = files;
  if (!file || !/^-?\d+$/.test(deg ?? '') || Number(deg) % 90) fail('usage: pdf rotate file.pdf 90|180|270 [--pages …] -o out.pdf');
  const doc = await load(file);
  for (const i of pagesOf(opts.pages, doc.getPageCount())) {
    const page = doc.getPage(i);
    page.setRotation(PDFLib.degrees((page.getRotation().angle + Number(deg) + 360) % 360));
  }
  await save(doc);
} else if (cmd === 'images') {
  if (!files.length) fail('give PNG or JPEG files');
  const doc = await PDFLib.PDFDocument.create();
  for (const f of files) {
    const bytes = await fs.readFile(f);
    const png = bytes[0] === 0x89 && bytes[1] === 0x50;
    const jpg = bytes[0] === 0xff && bytes[1] === 0xd8;
    if (!png && !jpg) fail(`${f}: only PNG and JPEG pictures`);
    const img = png ? await doc.embedPng(bytes) : await doc.embedJpg(bytes);
    doc.addPage([img.width, img.height]).drawImage(img, { x: 0, y: 0, width: img.width, height: img.height });
  }
  await save(doc);
} else if (cmd === 'from-text') {
  if (!files[0]) fail('which file?');
  const src = await fs.readText(files[0]);
  const md = /\.md$/i.test(files[0]);
  opts.out ??= files[0].replace(/\.[^./]+$/, '') + '.pdf';
  const doc = await PDFLib.PDFDocument.create();
  const fonts = { body: await doc.embedFont(PDFLib.StandardFonts.Helvetica), bold: await doc.embedFont(PDFLib.StandardFonts.HelveticaBold), mono: await doc.embedFont(PDFLib.StandardFonts.Courier) };
  doc.setTitle(opts.title ?? (/^#\s+(.+)$/m.exec(src)?.[1] ?? files[0].replace(/^.*\//, '')));
  // The standard fonts only have Western European letters: others become '?'.
  const safe = (t) => t.replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[–—]/g, '-').replace(/…/g, '...').replace(/[^\x20-\x7e\xa0-\xff]/g, '?');
  const [W, H, M] = [595.28, 841.89, 56];
  let page = doc.addPage([W, H]);
  let y = H - M;
  const line = (text, font, size, gap = 1.35) => {
    if (y - size < M) {
      page = doc.addPage([W, H]);
      y = H - M;
    }
    page.drawText(text, { x: M, y: y - size, size, font });
    y -= size * gap;
  };
  const wrap = (text, font, size) => {
    const words = safe(text).split(/(\s+)/);
    let cur = '';
    for (const w of words) {
      if (cur && font.widthOfTextAtSize((cur + w).trimEnd(), size) > W - 2 * M) {
        line(cur.trimEnd(), font, size);
        cur = w.trimStart();
      } else cur += w;
    }
    line(cur.trimEnd(), font, size);
  };
  let code = false;
  for (const raw of src.replace(/\r\n?/g, '\n').split('\n')) {
    if (md && /^\s*```/.test(raw)) {
      code = !code;
      continue;
    }
    if (code) {
      line(safe(raw) || ' ', fonts.mono, 9.5, 1.3);
      continue;
    }
    const h = md && /^(#{1,6})\s+(.*)$/.exec(raw);
    if (h) {
      y -= 6;
      wrap(h[2].replace(/[*_`]/g, ''), fonts.bold, [20, 16, 13.5, 12, 11, 11][h[1].length - 1]);
      y -= 2;
    } else if (!raw.trim()) y -= 7;
    else wrap(md ? raw.replace(/\*\*|__|`/g, '').replace(/(^|\W)[*_](\S[^*_]*?)[*_](?=\W|$)/g, '$1$2').replace(/^\s*[-*+]\s+/, '• ').replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1 ($2)') : raw, fonts.body, 11);
  }
  await save(doc);
} else fail(`unknown command ${cmd}\n${usage}`);

// docx: read Word documents (mammoth).
const mammoth = require('lib/mammoth.browser.min.js');
const usage = `usage: docx <command> file.docx [-o out]
  docx text file.docx     the text
  docx html file.docx     HTML (headings, lists, tables, links, pictures inline)
  docx md file.docx       Markdown`;
let out = null;
const rest = [];
for (let i = 0; i < args.length; i++) {
  if (args[i] === '-h' || args[i] === '--help') return print(usage);
  if (args[i] === '-o' || args[i] === '--output') out = args[++i];
  else rest.push(args[i]);
}
const [cmd, file] = rest;
if (!cmd || !file) return print(usage);
const bytes = await fs.readFile(file);
const input = { arrayBuffer: bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) };
const r = cmd === 'text' ? await mammoth.extractRawText(input) : cmd === 'html' ? await mammoth.convertToHtml(input) : cmd === 'md' ? await mammoth.convertToMarkdown(input) : null;
if (!r) {
  console.error(`docx: unknown command ${cmd}\n${usage}`);
  exit(2);
}
for (const m of r.messages ?? []) if (m.type === 'error') console.error(`docx: ${m.message}`);
if (out) {
  await fs.writeFile(out, r.value);
  print(`wrote ${out}`);
} else console.log(r.value.replace(/\n+$/, ''));

// ffmpeg and ffprobe (FFmpeg 6 compiled to WebAssembly by ffmpeg.wasm, one thread).
// Files named in the arguments are copied in; files it writes are copied back.
const createFFmpegCore = require('lib/ffmpeg-core.js');
const probe = args[0] === '--ffprobe';
const argv = probe ? args.slice(1) : args;
if (!argv.length || argv[0] === '-h' && argv.length === 1) {
  return print(`usage: ${probe ? 'ffprobe' : 'ffmpeg'} [options] (as FFmpeg's own)
  e.g. ffmpeg -i in.mov -vf scale=1280:-2 out.mp4
       ffmpeg -i talk.mp4 -vn -c:a libmp3lame talk.mp3
       ffmpeg -i clip.mp4 -ss 3 -frames:v 1 frame.png
       ffprobe -hide_banner in.mp4
Files are read from and written to the working folder. One thread, so big
videos take a while; a run may last 10 minutes at most.`);
}
const cwd = env.PWD || '/';
const abs = (p) => (p.startsWith('/') ? p : `${cwd.replace(/\/$/, '')}/${p}`).replace(/\/\.\//g, '/');
// The core reads where its files are from its script address (#base64 JSON); the WebAssembly is given here.
const core = await createFFmpegCore({ wasmBinary: await asset('lib/ffmpeg-core.wasm'), mainScriptUrlOrBlob: `ffmpeg-core.js#${btoa(JSON.stringify({ wasmURL: 'ffmpeg-core.wasm', workerURL: '' }))}` });
core.setLogger(({ type, message }) => (type === 'stdout' ? console.log : console.error)(message));
const FS = core.FS;
const mkdirs = (dir) => {
  let cur = '';
  for (const part of dir.split('/').filter(Boolean)) {
    cur += `/${part}`;
    try {
      FS.mkdir(cur);
    } catch {
      /* exists */
    }
  }
};
mkdirs(cwd);
FS.chdir(cwd);
// Inputs: every argument that names a file in the box.
const copied = new Map();
for (const a of argv) {
  if (a.startsWith('-') || /^[a-z]+:\/\//i.test(a)) continue;
  for (const cand of [a, ...a.split(/[=:,]/).filter((x) => /\.[a-z0-9]{2,5}$/i.test(x))]) {
    const path = abs(cand);
    if (copied.has(path) || !(await fs.exists(cand))) continue;
    const bytes = await fs.readFile(cand).catch(() => null);
    if (!bytes) continue;
    mkdirs(path.replace(/\/[^/]*$/, ''));
    FS.writeFile(path, bytes);
    copied.set(path, FS.stat(path).mtime.getTime());
  }
}
// The folders it may write to: the working folder and those named in the arguments.
const dirs = new Set([cwd]);
for (const a of argv) if (!a.startsWith('-') && a.includes('/')) dirs.add(abs(a).replace(/\/[^/]*$/, '') || '/');
for (const d of dirs) mkdirs(d);
// ffprobe in this build ends without setting its exit code (-1, "not finished"): that is success.
const ret = probe ? core.ffprobe(...argv) : core.exec(...argv);
const code = probe && ret === -1 ? 0 : ret;
// Anything new or changed goes back into the box.
const written = [];
for (const d of dirs) {
  let names = [];
  try {
    names = FS.readdir(d).filter((n) => n !== '.' && n !== '..');
  } catch {
    continue;
  }
  for (const n of names) {
    const path = `${d === '/' ? '' : d}/${n}`;
    const st = FS.stat(path);
    if (FS.isDir(st.mode)) continue;
    if (copied.has(path) && copied.get(path) === st.mtime.getTime()) continue;
    await fs.writeFile(path, FS.readFile(path));
    written.push(path.startsWith(`${cwd}/`) ? path.slice(cwd.length + 1) : path);
  }
}
if (written.length) console.error(`(wrote ${written.join(', ')})`);
if (code !== 0) exit(code === undefined ? 1 : code);

// ocr: text from pictures (Tesseract 5, LSTM, compiled to WebAssembly by tesseract.js).
const TesseractCore = require('lib/tesseract-core-simd-lstm.wasm.js');
const usage = `usage: ocr picture.(png|jpg|webp|bmp|tif) … [-o out.txt] [--psm N]
  Prints the text it reads (English). Several pictures: one after the other.
  --psm 6   treat the picture as one block of text (default 3: find the layout)
  --psm 7   a single line,  --psm 11  scattered text
For a scanned PDF, make pictures of its pages first (e.g. ffmpeg, or ask the agent).`;
let out = null;
let psm = null;
const files = [];
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === '-h' || a === '--help') return print(usage);
  if (a === '-o' || a === '--output') out = args[++i];
  else if (a === '--psm') psm = args[++i];
  else files.push(a);
}
if (!files.length) return print(usage);
const gz = await asset('data/eng.traineddata.gz');
const lang = new Uint8Array(await new Response(new Blob([gz]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());
const tm = await TesseractCore({ print: () => {}, printErr: () => {} });
tm.FS.writeFile('/eng.traineddata', lang);
const api = new tm.TessBaseAPI();
// OEM 1: the LSTM engine (the only one in this build).
if (api.Init(null, 'eng', 1) === -1) {
  console.error('ocr: the English language data could not be loaded');
  exit(1);
}
if (psm) api.SetVariable('tessedit_pageseg_mode', String(psm));
const texts = [];
for (const f of files) {
  const image = await fs.readFile(f);
  tm.FS.writeFile('/input', image);
  if (api.SetImageFile(1, 0) === 1) {
    console.error(`ocr: ${f}: cannot read this picture (PNG, JPEG, WebP, BMP or TIFF)`);
    exit(1);
  }
  const text = api.GetUTF8Text().trim();
  const conf = api.MeanTextConf();
  texts.push(files.length > 1 ? `--- ${f} (confidence ${conf}%) ---\n${text}` : text);
  if (files.length === 1) console.error(`(confidence ${conf}%)`);
}
api.End();
const all = texts.join('\n\n');
if (out) {
  await fs.writeFile(out, all);
  print(`wrote ${out}`);
} else print(all || '(no text found)');
